import {projects,about,home,resume,contact} from './content.js';
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const caseURL=id=>`?path=${home(id)}&project=${id}&view=case#case-${id}`;
export const caseLink=(id,label=projects[id].title)=>`<a class="text-link" href="${caseURL(id)}" data-case="${id}">${escape(label)}</a>`;
const playIcon='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m6 3 11 7-11 7Z" fill="currentColor"/></svg>';
export function videoMarkup(p,key,{native=false,sketch,caption}={}){const v=p.video;if(!v)return '';return `<figure class="video-evidence ${sketch?'has-sketch':''}" data-media="${key}" data-silent="${v.silent===true}"><div class="taped-video"><div class="video-surface"><video ${native?'controls':''} playsinline muted preload="none" poster="${v.poster}" aria-label="${escape(p.title)} — ${escape(v.caption)}"><source src="${v.src}" type="video/mp4"><a href="${v.src}">Open recording</a></video>${sketch?`<img class="media-sketch" src="${sketch}" alt="Editorial pencil illustration for ${escape(p.title)}">`:''}${native?'':`<button class="play-overlay" type="button" data-play aria-label="Play demo — ${escape(p.title)}">${playIcon}<span>Play demo</span></button>`}</div>${native?'':`<div class="media-controls"><button type="button" data-play>${playIcon}<span>Play demo</span></button><span class="media-time" aria-label="Playback time">0:00</span><button type="button" data-sound aria-pressed="false" ${v.silent?'disabled title="This recording has no audio track"':''}>${v.silent?'No audio':'Sound off'}</button><button type="button" data-fullscreen>Expand</button><label class="seek-label"><span class="sr-only">Seek ${escape(p.title)} recording</span><input type="range" data-seek min="0" max="100" step="0.1" value="0" aria-label="Seek ${escape(p.title)} recording" aria-valuetext="Not started"></label></div><p class="media-error" role="status" hidden>Video unavailable. The still and description remain available. <a href="${v.src}">Open recording</a></p>`}</div><figcaption>${sketch?'<span class="sketch-caption">Editorial sketch</span>':''}<span class="recording-caption">${escape(caption||v.caption)}${v.silent?' Silent.':''}</span></figcaption><details class="video-description"><summary>What the recording shows</summary><p>${escape(v.description)}</p></details></figure>`;}

function figures(items,caption){return `<figure class="evidence"><div class="figure-grid ${items.length===1?'single':''}">${items.map(([src,alt])=>`<div><p class="figure-label">${escape(alt)}</p><a class="image-link" href="${src}" target="_blank" rel="noopener" aria-label="Open full-size image: ${escape(alt)} (new tab)"><img src="${src}" alt="${escape(alt)}" loading="lazy"></a></div>`).join('')}</div>${caption?`<figcaption>${escape(caption)}</figcaption>`:''}</figure>`;}
const actions=p=>p.action?`<div class="actions"><a class="action" href="${p.action[1]}" target="_blank" rel="noopener">${escape(p.action[0])}<span class="sr-only"> (new tab)</span></a></div>`:'';
function aboutArticle(){
 const education=about.sections.find(s=>s.id==='education'),experience=about.sections.find(s=>s.id==='experience'),outside=about.sections.find(s=>s.id==='outside');
 return `<article class="case-article about-article about-journey" aria-labelledby="about"><header class="journey-greeting"><h2 id="about" tabindex="-1">${escape(about.title)}</h2></header><aside class="journey-aside"><figure class="journey-profile"><img class="about-photo" src="${about.photo}" width="280" height="370" alt="Samuel Frausto in a USC polo"><figcaption>${escape(about.subtitle)}</figcaption></figure><div class="journey-education" aria-label="Education"><p>${escape(education.paragraphs[0])}</p><p>${escape(education.paragraphs[1])}</p></div></aside><ol class="about-stages">${about.journey.map(stage=>`<li><h3 id="about-stage-${stage.id}">${escape(stage.title)}</h3>${stage.paragraphs.map(p=>`<p>${escape(p)}</p>`).join('')}</li>`).join('')}</ol><p class="journey-outside">${escape(outside.paragraphs[0])}</p><details class="about-experience"><summary>Experience<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 8 5 5 5-5" fill="none" stroke="currentColor" stroke-width="1.6"/></svg></summary><div>${experience.experience.map(([title,date,text,links])=>`<section class="experience"><h3>${escape(title)}</h3><p class="case-status">${escape(date)}</p><p>${escape(text)}</p><div class="inline-actions">${links.map(id=>caseLink(id).replace('<a ',`<a id="about-case-${id}" `)).join('')}</div></section>`).join('')}</div></details><div class="about-actions"><a class="action" href="${contact}">Say hello</a><a class="text-link" href="${resume}" target="_blank" rel="noopener">View résumé<span class="sr-only"> (new tab)</span></a></div></article>`;
}
export function article(id,{native=false,returnLabel='Back to work'}={}){if(id==='about')return aboutArticle();const p=id==='about'?about:projects[id],prefix=id==='about'?'about':`case-${id}`;return `<article class="case-article ${id==='about'?'about-article':''}" aria-labelledby="${prefix}"><header class="case-intro"><h2 id="${prefix}" tabindex="-1">${escape(p.title)}</h2>${p.photo?`<img class="about-photo" src="${p.photo}" width="280" height="370" alt="Samuel Frausto in a USC polo">`:''}${p.subtitle?`<p class="case-subtitle">${escape(p.subtitle)}</p>`:''}${p.status?`<p class="case-status">${escape(p.status)}</p>`:''}<p>${escape(p.intro||p.summary)}</p>${actions(p)}</header>${p.artifact?figures([p.artifact]):''}${p.sections.map(s=>`<section class="case-section" aria-labelledby="${id}-${s.id}"><h3 id="${id}-${s.id}" tabindex="-1">${escape(s.title)}</h3>${s.paragraphs.map(t=>`<p>${escape(t)}</p>`).join('')}${s.figures?figures(s.figures,s.caption):''}${s.quote?`<blockquote><p>From the original build plan</p><p>“${escape(s.quote)}”</p><footer>${escape(s.note)}</footer></blockquote>`:''}${s.experience?s.experience.map(([title,date,text,links])=>`<div class="experience"><h4>${escape(title)}</h4><p class="case-status">${date}</p><p>${escape(text)}</p><div class="inline-actions">${links.map(l=>caseLink(l)).join('')}</div></div>`).join(''):''}${s.links?`<div class="inline-actions">${s.links.map(([t,url])=>`<a class="text-link" href="${url}" target="_blank" rel="noopener">${escape(t)}<span class="sr-only"> (new tab)</span></a>`).join('')}</div>`:''}</section>`).join('')}${p.video?`<section class="case-section"><h3 id="${id}-recording" tabindex="-1">Recording</h3>${videoMarkup(p,'case-'+id,{native})}</section>`:''}${id==='about'?`<div class="actions"><a class="action" href="${resume}" target="_blank" rel="noopener">View résumé<span class="sr-only"> (new tab)</span></a><a class="utility" href="${contact}">Let’s talk</a></div>`:''}<footer class="case-footer"><a class="action" href="?path=${id==='about'?'about':home(id)}${id==='about'?'':`&project=${id}`}#map" data-return>${escape(returnLabel)}</a><a class="utility" href="${contact}">Email me</a></footer></article>`;}
export function contents(id){const p=id==='about'?about:projects[id];return `<details class="contents" open><summary>On this page</summary><nav aria-label="Case sections">${p.sections.map(s=>`<a href="#${id}-${s.id}" data-section>${escape(s.title)}</a>`).join('')}${p.video?`<a href="#${id}-recording" data-section>Recording</a>`:''}</nav></details>`;}
export function directory(){return `<article class="directory"><h2 id="all-work-heading" tabindex="-1">All work <span>(13)</span></h2><p>Thirteen projects. Explore any case.</p><ul>${Object.entries(projects).sort((a,b)=>a[1].title.localeCompare(b[1].title)).map(([id,p])=>`<li><a id="index-${id}" href="${caseURL(id)}" data-case="${id}">${escape(p.title)}</a><p>${escape(p.detail)}</p></li>`).join('')}</ul><a class="action" data-return href="#map">Back to work</a></article>`;}
export const utilityBar=({compact=false,returnLabel='Back to work'}={})=>`<nav class="reader-bar" aria-label="Reader utilities"><a href="#map" data-return>${escape(returnLabel)}</a>${compact?'':`<div><a href="?view=all#all-work-heading" data-all>All work (13)</a><a href="${resume}" target="_blank" rel="noopener">Résumé<span class="sr-only"> (new tab)</span></a><a href="${contact}">Contact</a></div>`}</nav>`;
